result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/assets.py", "content": """"Fixed asset register with straight-line depreciation and disposals.

All monetary amounts are integer cents. Full-year convention: a full
year of depreciation is charged for every year from the acquisition
year onward (capped at the depreciable base).
"""


class AssetError(KeyError):
    """Raised when disposing an unknown or already-disposed asset."""


class Asset:
    def __init__(self, id, cost_cents, salvage_cents, life_years, acquired_year):
        if cost_cents < 0 or salvage_cents < 0:
            raise ValueError("cost and salvage must be non-negative")
        if life_years <= 0:
            raise ValueError("life_years must be positive")
        self.id = id
        self.cost_cents = cost_cents
        self.salvage_cents = salvage_cents
        self.life_years = life_years
        self.acquired_year = acquired_year
        self.disposed_year = None
        self.disposal_proceeds_cents = None

    @property
    def annual_depreciation_cents(self):
        depreciable = self.cost_cents - self.salvage_cents
        return depreciable // self.life_years

    def years_elapsed(self, year):
        """Completed full years of service through year-end `year`."""
        end = self.disposed_year if self.disposed_year is not None else year
        return max(0, min(end - self.acquired_year + 1 if self.disposed_year is not None else year - self.acquired_year + 1,
                          0)) if False else max(0, (end if False else year) - self.acquired_year + 1)

    def book_value_at(self, year):
        """Straight-line book value at the end of `year`, floored at salvage."""
        if self.disposed_year is not None and year > self.disposed_year:
            return 0
        years = max(0, year - self.acquired_year + 1)
        accumulated = min(years * self.annual_depreciation_cents,
                          self.cost_cents - self.salvage_cents)
        return self.cost_cents - accumulated

    def accumulated_depreciation_at(self, year):
        if self.disposed_year is not None and year > self.disposed_year:
            return 0
        years = max(0, year - self.acquired_year + 1)
        return min(years * self.annual_depreciation_cents,
                   self.cost_cents - self.salvage_cents)


class Register:
    def __init__(self):
        self._assets = {}

    def acquire(self, id, cost_cents, salvage_cents, life_years, acquired_year):
        if id in self._assets:
            raise ValueError(f"duplicate asset id: {id!r}")
        asset = Asset(id, cost_cents, salvage_cents, life_years, acquired_year)
        self._assets[id] = asset
        return asset

    def get(self, id):
        return self._assets[id]

    def book_value_at(self, id, year):
        return self.get(id).book_value_at(year)

    def dispose(self, id, year, proceeds_cents):
        """Dispose of an asset; returns gain (positive) or loss (negative) in cents."""
        try:
            asset = self._assets[id]
        except KeyError:
            raise AssetError(f"unknown asset: {id!r}") from None
        if asset.disposed_year is not None:
            raise AssetError(f"asset {id!r} already disposed in {asset.disposed_year}")
        asset.disposed_year = year
        asset.disposal_proceeds_cents = proceeds_cents
        book_value = asset.book_value_at(year)
        return proceeds_cents - book_value

    def total_accumulated_depreciation(self, year):
        return sum(a.accumulated_depreciation_at(year) for a in self._assets.values())
